package vn.rtr.aeris.phone06;
import java.io.*;import java.util.*;
/** Native input contract: neutral READY emits no wire; each ACTIVE sample is new. */
public final class ManualPolicy06{
 private String generation,lease,reason="EXPLICIT_ENABLE_REQUIRED";private long last=-1,readyAt=-1,acceptedAt=-1,lastSeq=0,lastWire=-1,sampledAt=-1,requestAt=-1;private int left=-1,right=-1,mode=-1,prior=-1,target=-1;private boolean armed=false,takeover=false,terminal=false,active=false,neutralDebt=false;private int[]axes={0,0,500,0};
 private IOException bad(String r){revoke(r);return new IOException(r);}private void time(long n)throws IOException{if(n<0||n<last)throw bad("MANUAL_CLOCK_REGRESSION");last=n;if(requestAt>=0&&n-requestAt>1500)throw bad("PHONE_MODE_OBSERVATION_TIMEOUT");}
 public void observe(int observed,boolean a,long n)throws IOException{time(n);mode=observed;armed=a;if(requestAt>=0){if(!a||observed!=target&&observed!=prior)throw bad("PHONE_MODE_TRANSITION_DEVIATION");if(observed==target){requestAt=-1;target=-1;}}else if(takeover&&a&&observed!=5&&observed!=6&&observed!=9)throw bad("PHONE_ASSISTED_MODE_DEVIATION");if(takeover&&(observed==6||observed==9)){revoke("AP_SAFE_MODE_OBSERVED");terminal=true;}if(!a&&enabled())revoke("DISARMED");}
 public void requestMode(int wanted,long n)throws IOException{time(n);if(!armed||requestAt>=0||!Arrays.asList(5,6,9).contains(wanted)||terminal)throw bad("PHONE_MODE_REQUEST_CONTEXT");revoke("EXPLICIT_MODE_CHANGE");prior=mode;target=wanted;requestAt=n;takeover=true;if(wanted==6||wanted==9)terminal=true;}
 public String acquire(String gen,long n,boolean healthy,boolean qualified,int x,int y,int z,int r)throws IOException{time(n);if(enabled()||!qualified||!healthy||!armed||mode!=5||requestAt>=0||terminal||x!=0||y!=0||z!=500||r!=0||neutralDebt)throw bad("MANUAL_NEUTRAL_LOITER_OWNER_REQUIRED");generation=gen;lease=UUID.randomUUID().toString();reason=null;readyAt=n;acceptedAt=-1;sampledAt=-1;lastSeq=0;left=right=-1;active=false;axes=new int[]{0,0,500,0};return lease;}
 public void pointer(String gen,String token,String slot,int id,long n)throws IOException{time(n);context(gen,token);if(id<0||id>65535||!slot.equals("left")&&!slot.equals("right")||slot.equals("left")&&(left>=0||id==right)||slot.equals("right")&&(right>=0||id==left))throw bad("MANUAL_POINTER_OWNERSHIP");if(slot.equals("left"))left=id;else right=id;}
 public void sample(String gen,String token,long seq,long sampled,long n,int l,int r,int x,int y,int z,int yaw)throws IOException{time(n);context(gen,token);if(seq!=lastSeq+1||seq>100000||sampled<0||sampled>n||n-sampled>150||sampled<sampledAt||active&&n-acceptedAt>=250||!active&&n-readyAt>=30000||l!=left||r!=right||l<0&&r<0||x< -1000||x>1000||y< -1000||y>1000||z<0||z>1000||yaw< -1000||yaw>1000||l<0&&(z!=500||yaw!=0)||r<0&&(x!=0||y!=0)||!active&&(x!=0||y!=0||z!=500||yaw!=0))throw bad("MANUAL_SAMPLE_CONTEXT_OR_AXES");lastSeq=seq;sampledAt=sampled;acceptedAt=n;axes=new int[]{x,y,z,yaw};active=true;}
 public void approveWire(String gen,String token,long n,boolean healthy)throws IOException{time(n);context(gen,token);if(!active||!healthy||!armed||mode!=5||requestAt>=0||n-acceptedAt>=250||n-sampledAt>150||lastWire>=0&&n-lastWire<50)throw bad("MANUAL_PREWIRE_AGE_RATE_OR_MODE");lastWire=n;neutralDebt=true;}
 public void approveNeutral(long n,boolean healthy)throws IOException{time(n);if(!neutralDebt||!healthy||!armed||mode!=5||requestAt>=0||lastWire>=0&&n-lastWire<50)throw bad("MANUAL_NEUTRAL_PREWIRE_HEALTH_OR_RATE");lastWire=n;}
 public void neutralWritten(){neutralDebt=false;axes=new int[]{0,0,500,0};}public boolean neutralRequired(){return neutralDebt;}
 public boolean expired(long n)throws IOException{time(n);return enabled()&&(active?n-acceptedAt>=250:n-readyAt>=30000);}public long age(long n){return acceptedAt<0?-1:n-acceptedAt;}public long sequence(){return lastSeq;}public long remaining(long n){return enabled()?Math.max(0,(active?acceptedAt+250:readyAt+30000)-n):0;}
 public boolean sameLease(String t,long seq){return lease!=null&&Objects.equals(lease,t)&&lastSeq==seq;}public boolean enabled(){return lease!=null;}public boolean active(){return enabled()&&active;}public boolean takenOver(){return takeover;}public boolean pending(){return requestAt>=0;}public int mode(){return mode;}public boolean armed(){return armed;}public int[]axes(){return axes.clone();}
 public void revoke(String r){lease=null;active=false;left=right=-1;reason=r;}private void context(String g,String t)throws IOException{if(!enabled()||!Objects.equals(generation,g)||!lease.equals(t))throw bad("MANUAL_LEASE_GENERATION_OR_REVOKED");}
 public Map<String,Object>snapshot(long n){return Data97.m("format","aeris-phone06-manual","enabled",enabled(),"active",active(),"phase",active()?"ACTIVE":enabled()?"NEUTRAL_READY_NO_ACTUATION":"REVOKED","lease",lease,"reason",reason,"mode",mode,"armed",armed,"takeover",takeover,"autonomousCompletionEligible",!takeover,"pendingMode",target,"modeRequestedAtMs",requestAt,"lastInputAtMs",acceptedAt,"lastSeq",lastSeq,"lastWireAtMs",lastWire,"leftPointer",left,"rightPointer",right,"axes",Arrays.asList(axes[0],axes[1],axes[2],axes[3]),"snapshotAtMs",n,"ttlMs",250,"maximumHz",20,"neutralRequired",neutralDebt);}
}
